/* Declared with gint's own font_t so the compiler lays the bitfield byte,
 * the pointers and the trailing metrics out exactly the way gint's
 * renderer reads them. */
static font_t const luc_font = {
    "Lucida Console",
    0, 0, 0, 0,              /* bold, italic, serif, mono */
    0,                       /* prop: fixed-width */
    13,                      /* line_height */
    13,                      /* data_height */
    57,                      /* block_count */
    293,                      /* glyph_count */
    0,                       /* char_spacing: advance == width == 8 px */
    (void *)luc_blocks,
    (void *)luc_data,
    { .width = 8, .storage_size = 4 }
};

font_t const *luc_font_get(void) { return &luc_font; }
